<script setup lang="ts">
import {onMounted,ref} from 'vue'
import SupportMissionPanel,{type Mission} from '@/components/SupportMissionPanel.vue'
import AppModal from '@/components/AppModal.vue'
import {request} from '@/services/quality'
interface SupportRequest{mission?:Mission|null;qualification?:string|null;qualification_note?:string|null;id:number;reference:string;title:string|null;description:string|null;contact:string|null;theme:string|null;availability:string|null;urgency:string;status:string;version:number;withdrawal_reason:string|null;submitted_at:string|null}
const summary=ref<Record<string,number>|null>(null)
const items=ref<SupportRequest[]>([]);const selected=ref<SupportRequest|null>(null);const loading=ref(false);const busy=ref(false);const allowed=ref(false);const error=ref('');const notice=ref('');const search=ref('');const status=ref('');const page=ref(1);const last=ref(1);const editor=ref(false);const detail=ref(false);const confirm=ref(false);const discard=ref(false);const command=ref('submit');const reason=ref('');const editingId=ref(0);const editingVersion=ref(1);const key=ref('');const initial=ref('');const form=ref({title:'',description:'',contact:'',theme:'',availability:'',urgency:'normal'})
const labels:Record<string,string>={draft:'Brouillon',submitted:'Soumise',withdrawn:'Retirée'}
async function load(){loading.value=true;error.value='';try{const d=await request<{data:SupportRequest[];last_page:number;summary?:Record<string,number>}>('/support/requests?'+new URLSearchParams({page:String(page.value),...(status.value?{status:status.value}:{}),...(search.value?{search:search.value}:{})}));summary.value=d.summary||null;items.value=d.data;last.value=d.last_page;allowed.value=true}catch(e){allowed.value=false;summary.value=null;items.value=[];error.value=(e as Error).message}finally{loading.value=false}}
function edit(row?:SupportRequest){error.value='';editingId.value=row?.id||0;editingVersion.value=row?.version||1;key.value=crypto.randomUUID();form.value={title:row?.title||'',description:row?.description||'',contact:row?.contact||'',theme:row?.theme||'',availability:row?.availability||'',urgency:row?.urgency||'normal'};initial.value=JSON.stringify(form.value);editor.value=true}
function closeEditor(){if(busy.value)return;if(JSON.stringify(form.value)!==initial.value)discard.value=true;else editor.value=false}
async function save(){busy.value=true;error.value='';try{await request('/support/requests'+(editingId.value?'/'+editingId.value:''),editingId.value?'PATCH':'POST',{...form.value,...(editingId.value?{version:editingVersion.value}:{request_key:key.value})});editor.value=false;detail.value=false;notice.value='Brouillon enregistré. Aucune mission créée ni accès accordé.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function decide(action:string){command.value=action;reason.value='';error.value='';confirm.value=true}
async function execute(){busy.value=true;error.value='';try{await request(`/support/requests/${selected.value!.id}/${command.value}`,'POST',{version:selected.value!.version,...(command.value==='withdraw'?{reason:reason.value}:{})});confirm.value=false;detail.value=false;notice.value=command.value==='submit'?'Demande soumise ; notification préparée. Aucun délai d’intervention garanti.':'Demande retirée. Les données et l’historique sont conservés.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function filterState(value:string){status.value=value;page.value=1;load()}
onMounted(load)
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 02 · DEMANDES SERVEUR</p><h1>Tableau de bord accompagnement</h1><p class="page-subtitle">Officine sélectionnée · brouillon privé, soumission explicite et suivi.</p></div><button v-if="allowed" class="button primary" @click="edit()">Demander un accompagnement</button><button class="button secondary" :disabled="loading||busy" @click="load">Actualiser</button></div><p v-if="error&&!editor&&!confirm" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><div v-if="allowed&&summary" class="stats-grid" aria-label="Synthèse des demandes visibles" :aria-busy="loading"><div v-for="(label,value) in labels" :key="value" class="stat-card"><span class="stat-top">{{value==='draft'?'Mes brouillons':label==='Soumise'?'Demandes soumises':'Demandes retirées'}}</span><strong>{{summary[value]}}</strong><span class="stat-note">{{value==='draft'?'Privés · votre compte uniquement':'Officine sélectionnée'}}</span><button class="button secondary small" :disabled="loading||busy" @click="filterState(String(value))">Afficher {{label.toLowerCase()}}</button></div></div><p v-if="allowed&&summary" class="module-disclaimer">Synthèse de toutes les demandes que vous êtes autorisé à consulter, indépendamment des filtres et de la pagination. Les demandes retirées restent conservées. Aucun indicateur de mission n’est calculé à ce stade.</p><div class="panel"><div class="panel-heading"><h2>Demandes d’accompagnement</h2></div><form class="table-toolbar" @submit.prevent="page=1;load()"><label class="search-field"><input v-model="search" aria-label="Rechercher une demande" maxlength="180" placeholder="Référence ou intitulé…"/></label><select v-model="status" aria-label="État de la demande"><option value="">Tous les états</option><option v-for="(label,value) in labels" :key="value" :value="value">{{label}}</option></select><button class="button secondary" :disabled="loading">Filtrer</button></form><p v-if="loading" class="form-body" role="status">Chargement des demandes…</p><div v-else class="table-scroll"><table><thead><tr><th>DEMANDE</th><th>THÈME</th><th>ÉTAT</th><th>SOUMISSION UTC</th><th>ACTION</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td>{{r.title||'Brouillon à compléter'}}<span class="table-subtitle">{{r.reference}} · v{{r.version}}</span></td><td>{{r.theme||'Non précisé'}}</td><td>{{labels[r.status]||r.status}}</td><td>{{r.submitted_at||'Non soumise'}}</td><td><button class="button secondary small" @click="selected=r;detail=true;error=''">Ouvrir</button></td></tr><tr v-if="!items.length"><td colspan="5" class="empty-state">{{allowed?'Aucune demande pour ces filtres. Les brouillons des autres auteurs ne sont pas visibles.':'Aucune donnée à afficher sans autorisation.'}}</td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="loading||page<=1" @click="page--;load()">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="loading||page>=last" @click="page++;load()">Suivant</button></div></div><p class="module-disclaimer">Premier parcours connecté du M2 : demandes côté officine, réservé actuellement aux administrateurs actifs avec MFA. Missions, pièces jointes et permissions déléguées seront intégrées dans les prochaines tranches. Aucun accès accompagnateur ou engagement contractuel n’est créé par une demande.</p>
<AppModal v-model="detail" :title="selected?.reference||'Demande'" size="wide"><div v-if="selected" class="form-body"><dl class="application-summary"><dt>Intitulé</dt><dd>{{selected.title||'À compléter'}}</dd><dt>Besoin</dt><dd style="white-space:pre-wrap">{{selected.description||'À compléter'}}</dd><dt>Contact</dt><dd>{{selected.contact||'À compléter'}}</dd><dt>Disponibilité</dt><dd>{{selected.availability||'À convenir'}}</dd><dt>Urgence déclarée</dt><dd>{{selected.urgency}} — aucun délai garanti</dd><dt>État</dt><dd>{{labels[selected.status]}} · v{{selected.version}}</dd><dt>Qualification BEG</dt><dd>{{({ready:'Prête pour une proposition',needs_information:'Informations complémentaires nécessaires',not_retained:'Non retenue à ce stade'} as Record<string,string>)[selected.qualification||'']||'Non qualifiée'}}</dd><dt>Note partagée par BEG</dt><dd style="white-space:pre-wrap">{{selected.qualification_note||'—'}}</dd><dt>Motif de retrait</dt><dd>{{selected.withdrawal_reason||'—'}}</dd></dl></div><SupportMissionPanel v-if="selected" :request-id="selected.id" :request-version="selected.version" :mission="selected.mission" :submitted="selected.status==='submitted'" @saved="detail=false;notice='Décision sur la mission enregistrée. Aucun accès accordé.';load()"/><template #footer><button class="button secondary" @click="detail=false">Fermer</button><template v-if="selected?.status==='draft'"><button class="button secondary" @click="edit(selected)">Modifier le brouillon</button><button class="button primary" @click="decide('submit')">Soumettre</button></template><button v-if="selected&&['draft','submitted'].includes(selected.status)&&selected.mission?.status!=='accepted'" class="button secondary" @click="decide('withdraw')">Retirer la demande</button></template></AppModal>
<AppModal :model-value="editor" title="Brouillon de demande" :busy="busy" size="wide" @update:model-value="closeEditor"><form id="support-request-form" class="form-body form-grid" @submit.prevent="save"><p v-if="error" class="alert error span-2" role="alert">{{error}}</p><label>Intitulé<input v-model="form.title" maxlength="180"/></label><label>Contact demandeur<input v-model="form.contact" maxlength="180"/></label><label class="span-2">Description du besoin<textarea v-model="form.description" maxlength="5000" rows="5"/></label><label>Thème déclaré<input v-model="form.theme" maxlength="120"/></label><label>Disponibilité souhaitée<input v-model="form.availability" maxlength="250"/></label><label>Urgence déclarée<select v-model="form.urgency"><option value="low">Faible</option><option value="normal">Normale</option><option value="high">Élevée</option></select></label><p class="module-disclaimer span-2">Le brouillon peut être incomplet. Intitulé, description et contact sont nécessaires à la soumission. Une urgence déclarée n’est pas une priorité garantie.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="closeEditor">Annuler</button><button class="button primary" :disabled="busy" form="support-request-form" type="submit">Enregistrer le brouillon</button></template></AppModal>
<AppModal v-model="confirm" :title="command==='submit'?'Soumettre la demande ?':'Retirer la demande ?'" :busy="busy"><form id="support-request-decision" class="form-body correction-form" @submit.prevent="execute"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>{{selected?.title||selected?.reference}}</p><label v-if="command==='withdraw'">Motif obligatoire<textarea v-model="reason" required maxlength="2000" rows="4"/></label><p v-else>La demande sera enregistrée comme soumise. Cette action ne crée ni mission ni accès à vos données pour l’entreprise.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="confirm=false">Annuler</button><button class="button primary" :disabled="busy" form="support-request-decision" type="submit">Confirmer</button></template></AppModal><AppModal v-model="discard" title="Abandonner les modifications ?"><div class="form-body"><p>Les modifications non enregistrées seront perdues.</p></div><template #footer><button class="button secondary" @click="discard=false">Continuer la saisie</button><button class="button danger" @click="discard=false;editor=false">Abandonner</button></template></AppModal></section></template>
